def count_colorings(triangle, colors, used_colors):
    if triangle == 4:
        return 1

    count = 0
    for color in colors:
        if triangle == 1:
            if color not in used_colors:
                count += count_colorings(triangle + 1, colors, used_colors + [color])
        elif triangle == 2:
            if color != used_colors[0] and color != used_colors[2]:
